// 冷读沿原托留→本人领读→本人回复→原发信人实领折叠；后来死亡/离场不能改写合法旧来源。
#include "visit_reply_detail.hpp"
#include "visit_reply_authored.hpp"
#include "visit_reply_life.hpp"
#include <set>
namespace hanmo::resident {namespace {
using Positions=std::map<StableId,std::size_t>;
// 实例分配与Common事实序必须同时在前；同tick也不能将后来消息移到原回复之前。
Status before(const CommonStore& c,const Positions& positions,const StableId& source,const StableId& kind,Integer tick,const StableId& boundary,const StableId& boundary_kind,Integer boundary_tick){const auto* head=c.state().facts.find(source);const auto a=visit_reply_detail::serial(source,kind,c.state().next_instance_id),b=visit_reply_detail::serial(boundary,boundary_kind,c.state().next_instance_id);const auto x=positions.find(source),y=positions.find(boundary);if(!head||head->id!=source||head->kind!=kind||!a||!b||*a>=*b||x==positions.end()||y==positions.end()||x->second>=y->second||tick<0||tick>boundary_tick)return common_failure("VisitReplySourceOrderMismatch",source);return common_success();}
// 原业务头/tick由外层核实后，两位实际会面者必须当时存在且在世；不用今天alive反推。
Status alive(const CommonStore& c,const CommonCatalog& catalog,const FamilyDeathOriginRead& deaths,const VisitMessageContact& contact,const StableId& fact,const VisitReplyLifeContext*life){for(const auto& person:{contact.actor_id,contact.custodian_actor_id}){const auto*header=c.state().facts.find(fact);if(!header)return common_failure("VisitReplyHistoricalSourceRequired",fact);auto read=life?life->people.read_presence_before_original_fact(person,contact.tick,{header->domain,header->kind,header->id}):read_actor_presence_before_fact(c,catalog,deaths,person,contact.tick,fact);if(!read.ok)return {false,{},read.error};if(!read.value.alive)return common_failure("VisitReplyHistoricalActorUnavailable",fact);}return common_success();}
Status contact(const CommonStore& c,const CommonCatalog& catalog,const InteractionCatalog& definitions,const FamilyDeathOriginRead& deaths,const VisitMessagePolicy& p,const VisitMessageContact& v,const StableId& actor,const StableId& node,const StableId& fact,const StableId& kind,const VisitReplyLifeContext*life){Integer actual_tick=c.tick();if(life){auto now=life->messages.clock.read_current_moment();if(!now.ok)return {false,{},now.error};actual_tick=now.value.half_day_tick;}const auto* role=definitions.common->roles.find(p.role_id);const auto number=visit_reply_detail::serial(fact,kind,c.state().next_instance_id),session=visit_reply_detail::serial(v.session_id,"interaction",c.state().next_instance_id);if(!role||v.actor_id!=actor||v.custodian_actor_id!=p.custodian_actor_id||v.place_id!=role->place_id||v.role_id!=p.role_id||v.dialogue_id!=p.dialogue_id||v.node_id!=node||v.tick<0||v.tick>actual_tick||!number||!session||*session>=*number)return common_failure("InvalidVisitReplyContact",fact);return alive(c,catalog,deaths,v,fact,life);}
}
Status validate_visit_reply_original_sources(const CommonStore& common,const CommonCatalog& common_catalog,const VisitMessageState& messages,const VisitMessageCatalog& originals,const InteractionCatalog& definitions,const VisitReplyCatalog& catalog,const VisitReplyState& state,const FamilyDeathOriginRead& deaths,const VisitReplyAuthorshipRead* authorship,const VisitReplyLifeContext*life){
    if(visit_reply_life_version(state.version)){if(!life)return common_failure("VisitReplyLife4SourcesRequired",{},ErrorKind::unsupported_capability);if(&life->messages.common!=&common||&life->messages.state!=&messages||&life->messages.policies!=&originals||&life->messages.interaction!=&definitions||&life->common_catalog!=&common_catalog||&life->policies!=&catalog||&life->state!=&state||life->authorship!=authorship)return common_failure("VisitReplyLifeCandidateMismatch",{},ErrorKind::internal);auto binding=validate_visit_reply_life_binding(*life);if(!binding.ok)return binding;}else if(life||!state.life_sources.empty())return common_failure("UnselectedVisitReplyLifeSources");
    auto valid=validate_visit_messages(common,messages,originals,definitions,life?&life->messages.clock:nullptr);if(!valid.ok)return valid;valid=validate_visit_reply_catalog(catalog,originals,definitions);if(!valid.ok)return valid;if(!visit_reply_version(state.version)||state.version!=catalog.version||state.posted.size()>65536||state.collected.size()>65536)return common_failure("InvalidVisitReplyState");
    Positions positions;std::size_t pos=0;for(const auto& head:common.state().facts.rows())positions.emplace(head.first,pos++);
    std::set<StableId> answered,delivered;std::vector<StableId> posted_order,collected_order;Integer previous_id=0,previous_tick=-1;
    for(const auto& row:common.state().facts.rows()){
        const auto& h=row.second;const bool posted=h.kind==visit_reply_posted_kind,collected=h.kind==visit_reply_collected_kind;if(!posted&&!collected){if(h.domain==visit_reply_module)return common_failure("UnknownVisitReplyFact",row.first);continue;}
        const auto number=visit_reply_detail::serial(row.first,h.kind,common.state().next_instance_id);if(h.id!=row.first||h.domain!=visit_reply_module||!number||*number<=previous_id)return common_failure("InvalidVisitReplyFact",row.first);previous_id=*number;
        const VisitMessageContact* source=nullptr;
        if(posted){const auto* reply=state.posted.find(row.first);const auto* policy=reply?visit_reply_detail::policy(catalog,reply->policy_id):nullptr;const auto* p=policy?visit_reply_detail::original(originals,policy->message_policy_id):nullptr;const auto* message=reply?messages.posted.find(reply->message_fact_id):nullptr;const auto* received=reply?messages.received.find(reply->received_fact_id):nullptr;
            if(!reply||reply->fact_id!=row.first||!p||!message||message->policy_id!=p->id||!received||received->message_fact_id!=message->fact_id||received->contact.actor_id!=p->recipient_actor_id||(reply->response!="declined"&&reply->response!="contact_in_person")||!answered.insert(message->fact_id).second)return common_failure("InvalidVisitReplySource",row.first);
            valid=before(common,positions,message->fact_id,visit_message_posted_kind,message->contact.tick,received->fact_id,visit_message_received_kind,received->contact.tick);if(!valid.ok)return valid;
            valid=before(common,positions,received->fact_id,visit_message_received_kind,received->contact.tick,row.first,h.kind,reply->contact.tick);if(!valid.ok)return valid;
            valid=alive(common,common_catalog,deaths,message->contact,message->fact_id,life);if(!valid.ok)return valid;valid=alive(common,common_catalog,deaths,received->contact,received->fact_id,life);if(!valid.ok)return valid;
            valid=contact(common,common_catalog,definitions,deaths,*p,reply->contact,p->recipient_actor_id,policy->reply_node_id,row.first,h.kind,life);if(!valid.ok)return valid;source=&reply->contact;posted_order.push_back(row.first);
        }else{const auto* receipt=state.collected.find(row.first);const auto* reply=receipt?state.posted.find(receipt->reply_fact_id):nullptr;const auto* policy=reply?visit_reply_detail::policy(catalog,reply->policy_id):nullptr;const auto* p=policy?visit_reply_detail::original(originals,policy->message_policy_id):nullptr;
            if(!receipt||receipt->fact_id!=row.first||!reply||!p||!answered.count(reply->message_fact_id)||!delivered.insert(reply->fact_id).second)return common_failure("InvalidVisitReplyCollection",row.first);
            valid=before(common,positions,reply->fact_id,visit_reply_posted_kind,reply->contact.tick,row.first,h.kind,receipt->contact.tick);if(!valid.ok)return valid;valid=contact(common,common_catalog,definitions,deaths,*p,receipt->contact,p->sender_actor_id,policy->collect_node_id,row.first,h.kind,life);if(!valid.ok)return valid;source=&receipt->contact;collected_order.push_back(row.first);
        }
        if(source->tick<previous_tick)return common_failure("VisitReplyChronologyMismatch",row.first);previous_tick=source->tick;
    }
    if(posted_order!=state.posted.order()||collected_order!=state.collected.order())return common_failure("VisitReplyFactCoverageMismatch");
    for(const auto& row:state.posted.rows())if(row.first!=row.second.fact_id)return common_failure("VisitReplyRecordKeyMismatch",row.first);for(const auto& row:state.collected.rows())if(row.first!=row.second.fact_id)return common_failure("VisitReplyRecordKeyMismatch",row.first);
    decltype(state.posted_by_author) posted_index;decltype(state.collected_by_sender) collected_index;for(const auto&row:state.posted.rows())posted_index[row.second.contact.actor_id].push_back(row.first);for(const auto&row:state.collected.rows())collected_index[row.second.contact.actor_id].push_back(row.first);if(posted_index!=state.posted_by_author||collected_index!=state.collected_by_sender)return common_failure("VisitReplyObserverIndexMismatch");return validate_visit_reply_authored_sources(common,originals,definitions,catalog,state,authorship);
}
Status validate_visit_replies(const CommonStore&c,const CommonCatalog&cc,const VisitMessageState&m,const VisitMessageCatalog&mc,const InteractionCatalog&i,const VisitReplyCatalog&p,const VisitReplyState&s,const FamilyDeathOriginRead&d,const VisitReplyAuthorshipRead*a,const VisitReplyLifeContext*life){auto valid=validate_visit_reply_original_sources(c,cc,m,mc,i,p,s,d,a,life);if(!valid.ok)return valid;return life?validate_visit_reply_life_sources(*life):common_success();}
}
